'use strict';
const $=id=>document.getElementById(id);
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const timeLabel=seconds=>`${Math.floor(Math.max(0,seconds||0)/60)}:${String(Math.floor(Math.max(0,seconds||0)%60)).padStart(2,'0')}`;
let state={songs:[],jobs:[],queue:[],playback:{playing:false,song:null,position:0},settings:{},broadcast:{}};
let settingsLoaded=false,refreshing=false,toastTimeout,libraryStamp='',queueStamp='',jobsStamp='',monitorSource='',lastPlayback=null;
let monitorWanted=false;
function toast(message,error=false){const el=$('toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.hidden=true,error?9000:4500);}
async function api(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Station-Request':'1'},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('The station is starting. Try again in a moment.');}if(!response.ok){const detail=data.detail||data.error;throw new Error(typeof detail==='string'?detail:'Check the fields and try again.');}return data;}
function changeView(name){if(!['studio','library','broadcast','settings'].includes(name))return;document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.id===`view-${name}`));document.querySelectorAll('.nav').forEach(nav=>nav.classList.toggle('active',nav.dataset.view===name));$('page-label').textContent=name[0].toUpperCase()+name.slice(1);location.hash=name;}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>changeView(button.dataset.view)));
changeView(location.hash.slice(1)||'studio');
window.addEventListener('hashchange',()=>changeView(location.hash.slice(1)||'studio'));

let sourceSongId=null,timedDuration='180';
const MUSIC_DEFAULTS={ending_mode:'natural',safety_seconds:240,planning_mode:'full',abc:'',planning_seed:null,decoder_seed:null,temperature:1,top_p:.95,top_k:100,repetition_penalty:1.2,planning_temperature:.7,planning_top_p:.9,planning_top_k:30,planning_repetition_penalty:1.005,planning_penalty_window:100,max_abc_tokens:8192,steps:32,cfg:1,sampler:'dpm_2',scheduler:'sgm_uniform',denoise:1};
const musicFields={ending_mode:'ending-mode',safety_seconds:'safety-seconds',planning_mode:'planning-mode',abc:'abc',planning_seed:'planning-seed',decoder_seed:'decoder-seed',temperature:'music-temperature',top_p:'music-top-p',top_k:'music-top-k',repetition_penalty:'music-repetition',planning_temperature:'planning-temperature',planning_top_p:'planning-top-p',planning_top_k:'planning-top-k',planning_repetition_penalty:'planning-repetition',planning_penalty_window:'planning-window',max_abc_tokens:'max-abc-tokens',steps:'render-steps',cfg:'render-cfg',sampler:'render-sampler',scheduler:'render-scheduler',denoise:'render-denoise'};
const textMusicFields=new Set(['ending_mode','planning_mode','abc','sampler','scheduler']);
function seedValue(id){const value=$(id).value.trim();if(!value)return null;if(!/^[0-9]+$/.test(value)||BigInt(value)>18446744073709551615n)throw new Error('Seeds must be whole numbers from 0 to 18446744073709551615.');return value;}
function selectValue(id,value){const el=$(id);const text=String(value??'');if(el.tagName==='SELECT'&&!Array.from(el.options).some(o=>o.value===text))el.add(new Option(text,text));el.value=text;}
function setMusic(values={}){const settings={...MUSIC_DEFAULTS,...values,safety_seconds:240};for(const [key,id]of Object.entries(musicFields))selectValue(id,settings[key]);updateEnding();}
function readMusic(){const result={};for(const [key,id]of Object.entries(musicFields)){result[key]=key.endsWith('_seed')?seedValue(id):textMusicFields.has(key)?$(id).value:Number($(id).value);}if(result.planning_mode==='off')result.abc='';return result;}
function updateEnding(){const natural=$('ending-mode').value==='natural';const length=$('duration');if(natural){if(length.value!=='auto')timedDuration=String(Math.min(240,Math.max(15,Number(length.value)||180)));length.value='auto';}else if(length.value==='auto'){selectValue('duration',timedDuration);}length.disabled=natural;$('duration-field').classList.toggle('field-disabled',natural);$('ending-hint').textContent=natural?'The song chooses its own ending, up to 4 minutes. An unfinished take at the limit is held for review.':'Choose a limit up to 4 minutes. Timed clips can end before the music is complete.';$('abc').disabled=$('planning-mode').value==='off';}
$('ending-mode').addEventListener('change',updateEnding);$('planning-mode').addEventListener('change',updateEnding);
$('reset-music').addEventListener('click',()=>{setMusic();toast('Model controls reset to the working defaults.');});
function clearTake(){sourceSongId=null;$('take-context').hidden=true;$('cover-choice').hidden=false;$('use-cover').disabled=false;$('reuse-cover-note').hidden=true;$('generate-button').innerHTML='<span>✦</span> Generate song <span class="button-arrow">↗</span>';}
$('clear-take').addEventListener('click',()=>{clearTake();$('seed').value='';setMusic();toast('Ready for a fresh song. Your writing is still in the form.');});
function editTake(song){sourceSongId=song.id;$('take-context').hidden=false;$('take-label').textContent=`New take of “${song.title}”`;$('cover-choice').hidden=true;$('use-cover').disabled=true;$('reuse-cover-note').hidden=false;$('generate-button').innerHTML='<span>✦</span> Generate new take <span class="button-arrow">↗</span>';$('description').value=song.description||'';selectValue('genre',song.genre);selectValue('vocal',song.vocal);selectValue('duration',Math.min(240,Math.max(15,song.target_duration||Math.round(song.duration)||180)));$('song-title').value=song.title||'';$('lyrics').value=song.lyrics||'';$('style-override').value=song.style||'';$('seed').value=song.seed??'';setMusic(Object.keys(song.music||{}).length?song.music:{decoder_seed:'42',planning_seed:song.seed??null});changeView('studio');$('description').focus();}
async function musicOptions(){try{const options=await api('/api/music/options');for(const [id,key]of [['render-sampler','samplers'],['render-scheduler','schedulers']]){const el=$(id),value=el.value;const values=options[key];if(Array.isArray(values)&&values.length){el.replaceChildren(...values.map(v=>new Option(v,v)));selectValue(id,value);}}$('music-options-status').textContent='Sampler choices loaded from your installed music engine. Model: YuE2 INT8.';}catch{$('music-options-status').textContent='Music engine unavailable. Working defaults remain selected.';}}
setMusic();musicOptions();

const presets={country:{description:'An uplifting country song about taking the long way home. Warm acoustic guitar, expressive female vocals, pedal steel, and a chorus that feels like an open road at sunset.',genre:'Country',vocal:'Female'},pop:{description:'A bright, heartfelt pop song about starting over in a new city. Shimmering synths, a warm bass line, intimate verses and a soaring, memorable chorus.',genre:'Pop',vocal:'Female'},blues:{description:'A late-night blues song about the last conversation in an empty diner. Soulful male vocals, clean electric guitar, brushed drums and a slow, easy groove.',genre:'Blues',vocal:'Male'}};
document.querySelectorAll('[data-preset]').forEach(button=>button.addEventListener('click',()=>{const preset=presets[button.dataset.preset];$('description').value=preset.description;$('genre').value=preset.genre;$('vocal').value=preset.vocal;$('description').focus();}));
$('generate-form').addEventListener('submit',async event=>{
 event.preventDefault();const button=$('generate-button');button.disabled=true;
 try{const payload={description:$('description').value.trim(),genre:$('genre').value,vocal:$('vocal').value,duration:$('ending-mode').value==='natural'?180:Number($('duration').value),seed:seedValue('seed'),title:$('song-title').value.trim(),lyrics:$('lyrics').value.trim(),style:$('style-override').value.trim(),music:readMusic(),auto_queue:$('auto-queue').checked};
 for(const key of ['seed','lyrics','title','style'])if(payload[key]===null||payload[key]==='')delete payload[key];
 if(sourceSongId){await api(`/api/songs/${sourceSongId}/regenerate`,payload);}else{payload.use_cover=$('use-cover').checked;await api('/api/songs',payload);}
 toast(sourceSongId?'New take queued. The original and its cover are preserved.':'Song queued. Follow its progress at the production desk.');await refresh();
 }catch(error){toast(error.message,true);}finally{button.disabled=false;}
});
function asset(song,kind){const value=song?.assets?.[kind];return typeof value==='string'&&value.startsWith('/media/')?value:'';}
function download(song,kind){const url=asset(song,kind);return url?url+(url.includes('?')?'&':'?')+'download=1':'';}

function songActions(song,review){
 const files=[['audio','Download audio'],['landscape','Download wide video'],['portrait','Download vertical video'],['cover','Download cover']].filter(([kind])=>asset(song,kind));
 return `<details class="song-menu" name="song-actions" data-song-menu="${song.id}"><summary aria-label="Actions for ${escapeHtml(song.title)}" title="Song actions"><span aria-hidden="true">⋮</span></summary><div class="song-menu-panel"><span class="song-menu-heading">Song actions</span>${!review?`<button type="button" data-action="queue" data-song="${song.id}" ${state.queue.includes(song.id)?'disabled':''}>${state.queue.includes(song.id)?'Already in queue':'Add to queue'}</button>`:''}<button type="button" data-action="${review?'finish':'edit'}" data-song="${song.id}">${review?'Adjust for 4 minutes':'Adjust & new take'}</button><button type="button" data-action="cover" data-song="${song.id}" ${review?'disabled':''}>Create new cover</button><div class="song-menu-divider"></div>${files.map(([kind,label])=>`<a href="${escapeHtml(download(song,kind))}">${label}</a>`).join('')}<div class="song-menu-divider"></div><button type="button" class="delete-song-action" data-action="delete" data-song="${song.id}">Delete song…</button></div></details>`;
}
function closeSongMenus(){document.querySelectorAll('.song-menu[open]').forEach(menu=>menu.open=false);}
document.addEventListener('click',event=>{if(!event.target.closest('.song-menu'))closeSongMenus();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){const open=document.querySelector('.song-menu[open]');if(open){open.open=false;open.querySelector('summary').focus();}}});
let deleteSongId=null,deletingSong=false;
function askDeleteSong(song){deleteSongId=song.id;$('delete-song-title').textContent=`Delete “${song.title}”?`;$('delete-song-error').hidden=true;$('delete-song-error').textContent='';$('delete-song-confirm').disabled=false;$('delete-song-dialog').showModal();$('delete-song-cancel').focus();}
$('delete-song-cancel').addEventListener('click',()=>{if(!deletingSong)$('delete-song-dialog').close();});
$('delete-song-dialog').addEventListener('cancel',event=>{if(deletingSong)event.preventDefault();});
$('delete-song-dialog').addEventListener('close',()=>{deleteSongId=null;});
$('delete-song-form').addEventListener('submit',async event=>{
 event.preventDefault();if(deletingSong||!deleteSongId)return;deletingSong=true;const id=deleteSongId;$('delete-song-confirm').disabled=true;$('delete-song-cancel').disabled=true;$('delete-song-error').hidden=true;
 try{const result=await api(`/api/songs/${id}/delete`,{confirmed:true});if(sourceSongId===id)clearTake();$('delete-song-dialog').close();await refresh();$('library-search').focus();toast(result.warning||'Song and saved media deleted.',!!result.warning);}
 catch(error){$('delete-song-error').textContent=error.message;$('delete-song-error').hidden=false;}
 finally{deletingSong=false;$('delete-song-confirm').disabled=false;$('delete-song-cancel').disabled=false;}
});

function renderLibrary(){
 const query=$('library-search').value.trim().toLowerCase();const all=state.songs.filter(song=>['ready','needs_review'].includes(song.status));const songs=all.filter(song=>`${song.title} ${song.genre} ${song.description}`.toLowerCase().includes(query));const ready=all.filter(song=>song.status==='ready');const reviews=all.length-ready.length;
 $('library-count').textContent=all.length;$('library-summary').textContent=`${ready.length} ready · ${timeLabel(ready.reduce((sum,s)=>sum+s.duration,0))}${reviews?` · ${reviews} need ending review`:''}`;
 const stamp=JSON.stringify([songs,state.queue]);if(stamp===libraryStamp)return;libraryStamp=stamp;
 if(!songs.length){$('library').innerHTML=`<div class="panel empty-library"><h2>${query?'No matching songs.':'Room for your first record.'}</h2><p>${query?'Try another title or genre.':'Every finished song, cover, and broadcast video will live here.'}</p><button class="button primary" data-action="create">Create a song</button></div>`;return;}
 $('library').innerHTML=songs.map(song=>{const review=song.status==='needs_review';const music=song.music||{};const completion=song.completion||{};const abc=song.abc||completion.abc||'';const status=review?'Ending needs review':music.ending_mode==='clip'?'Timed clip':completion.semantic_truncated===false?'Model reached its ending':'Earlier take';
 return `<article class="song-card">${songActions(song,review)}<img src="${escapeHtml(asset(song,'cover'))}" alt="Cover for ${escapeHtml(song.title)}" loading="lazy"><div class="song-card-content"><span class="take-status ${review?'review':''}">${status}</span><h3>${escapeHtml(song.title)}</h3><p>${escapeHtml(song.genre)} · ${timeLabel(song.duration)} · ${song.cover_source==='station'?'Station artwork':'AI cover'}</p>${song.warning?`<p class="song-warning">${escapeHtml(song.warning)}</p>`:''}
 ${review?`<audio controls preload="none" src="${escapeHtml(asset(song,'audio'))}" aria-label="Review ${escapeHtml(song.title)}"></audio>`:''}
 ${!review?`<div class="card-actions"><button class="button primary" data-action="play" data-song="${song.id}">▶ Play</button></div>`:''}
 <details class="song-details"><summary>Lyrics, score & settings</summary><p>${escapeHtml(song.description)}</p>${song.style?`<p><strong>Style:</strong> ${escapeHtml(song.style)}</p>`:''}<p class="song-settings">Music seed: ${escapeHtml(song.seed??music.seed??'Not recorded')}<br>Planning: ${escapeHtml(music.planning_mode||'Earlier default')} · Render: ${escapeHtml(music.steps??32)} steps / ${escapeHtml(music.sampler||'dpm_2')} / ${escapeHtml(music.scheduler||'sgm_uniform')}</p>${song.lyrics?`<pre>${escapeHtml(song.lyrics)}</pre>`:''}${abc?`<label>Saved ABC score<textarea readonly spellcheck="false">${escapeHtml(abc)}</textarea></label><button class="text-button" data-action="score" data-song="${song.id}">Use this score for a new take</button>`:''}<details><summary>All saved model controls</summary><pre class="song-settings">${escapeHtml(JSON.stringify(music,null,2))}</pre></details></details></div></article>`;}).join('');
}
$('library-search').addEventListener('input',renderLibrary);
$('library').addEventListener('click',async event=>{
 if(event.target.closest('.song-menu a')){closeSongMenus();return;}const button=event.target.closest('[data-action]');if(!button)return;closeSongMenus();const id=button.dataset.song;const song=state.songs.find(s=>s.id===id);button.disabled=true;
 try{switch(button.dataset.action){
 case'create':clearTake();changeView('studio');break;
 case'delete':askDeleteSong(song);break;
 case'edit':editTake(song);break;
 case'score':editTake(song);$('abc').value=song.abc||song.completion?.abc||'';if($('planning-mode').value==='off')$('planning-mode').value='full';updateEnding();$('abc').closest('details').open=true;document.querySelector('.control-details').open=true;$('abc').focus();break;
 case'finish':editTake(song);$('ending-mode').value='natural';updateEnding();$('lyrics').closest('details').open=true;$('lyrics').focus();toast('Adjust the lyrics or score so this new take can finish within 4 minutes.');break;
 case'play':monitorWanted=true;await api('/api/playback',{action:'play_song',song_id:id});changeView('studio');break;
 case'queue':await api('/api/queue',{song_id:id,action:'add'});toast('Added to your station queue.');break;
 case'cover':if(!state.settings.key_configured){changeView('settings');openKeyEditor();toast('Add your existing OpenAI key to create this cover.');break;}await api(`/api/songs/${id}/cover`,{});toast('Cover request queued. This uses your OpenAI API account.');break;
 }await refresh();}catch(error){toast(error.message,true);}finally{button.disabled=false;}
});
function renderQueue(){const songs=state.queue.map(id=>state.songs.find(s=>s.id===id)).filter(s=>s?.status==='ready');const stamp=JSON.stringify([songs,state.playback.song?.id]);if(stamp===queueStamp)return;queueStamp=stamp;if(!songs.length){$('queue').innerHTML='<div class="empty-inline">Add a finished song to start your station.</div>';return;}$('queue').innerHTML=songs.map((song,index)=>`<div class="queue-row"><span class="queue-number">${state.playback.song?.id===song.id?'▶':String(index+1).padStart(2,'0')}</span><img src="${escapeHtml(asset(song,'cover'))}" alt=""><div class="queue-text"><strong>${escapeHtml(song.title)}</strong><span>${escapeHtml(song.genre)} · ${timeLabel(song.duration)}</span></div><button class="icon-button" data-id="${song.id}" data-action="up" aria-label="Move ${escapeHtml(song.title)} earlier" ${index===0?'disabled':''}>↑</button><button class="icon-button" data-id="${song.id}" data-action="down" aria-label="Move ${escapeHtml(song.title)} later" ${index===songs.length-1?'disabled':''}>↓</button><button class="icon-button" data-id="${song.id}" data-action="remove" aria-label="Remove ${escapeHtml(song.title)} from queue">×</button></div>`).join('');}
$('queue').addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button)return;try{await api('/api/queue',{song_id:button.dataset.id,action:button.dataset.action});await refresh();}catch(error){toast(error.message,true);}});
const stageLabels={queued:'Waiting for the music engine',writing:'Writing original lyrics locally',generating:'Composing and generating music',submitted:'Sending to music engine',cover:'Creating your song cover',packaging:'Preparing synchronized video',complete:'Generation complete',needs_review:'Ending needs review · held out of queue',completed:'Ready for your station',failed:'Needs attention',cancelled:'Cancelled',interrupted:'Interrupted by restart'};
function renderJobs(){const jobs=state.jobs.slice(0,5);const active=state.jobs.filter(j=>['queued','running'].includes(j.status)).length;$('job-count').textContent=`${active} active`;const stamp=JSON.stringify(jobs);if(stamp===jobsStamp)return;jobsStamp=stamp;$('jobs').innerHTML=jobs.length?jobs.map(job=>{const song=state.songs.find(s=>s.id===job.song_id);const failed=['failed','interrupted'].includes(job.status)||job.stage==='needs_review';return `<div class="job-row"><i class="job-meter ${job.status==='completed'?'done':failed?'error':''}"></i><div class="job-text"><strong>${escapeHtml(song?.title||'New session')}</strong><span>${escapeHtml(job.error||stageLabels[job.stage]||job.stage)}</span>${job.warning?`<span class="job-warning">${escapeHtml(job.warning)}</span>`:''}</div>${['queued','running'].includes(job.status)?`<button class="icon-button" data-cancel="${job.id}" aria-label="Cancel generation">×</button>`:''}</div>`;}).join(''):'<div class="empty-inline">Your generation progress will appear here.</div>';}
$('jobs').addEventListener('click',async event=>{const button=event.target.closest('[data-cancel]');if(!button)return;try{await api(`/api/jobs/${button.dataset.cancel}/cancel`,{});toast('Cancellation requested.');await refresh();}catch(error){toast(error.message,true);}});
function syncMonitor(playback){lastPlayback={...playback,received:Date.now()};const song=playback.song;const video=$('monitor');const desired=asset(song,'landscape');$('player-badge').textContent=playback.playing?'PLAYING':'STOPPED';$('play-button').textContent=playback.playing?'Ⅱ':'▶';$('play-button').setAttribute('aria-label',playback.playing?'Pause station':'Start station');$('current-title').textContent=song?.title||'Your station is waiting';$('current-description').textContent=song?`${song.genre} · ${song.cover_source==='station'?'Station artwork':'AI cover art'}`:'Generate a song or choose one from your library.';if(song){const cover=$('current-cover');const src=asset(song,'cover');if(cover.dataset.src!==src){cover.innerHTML=`<img src="${escapeHtml(src)}" alt="${escapeHtml(song.title)} cover">`;cover.dataset.src=src;}}else if($('current-cover').dataset.src){$('current-cover').innerHTML='<div class="record-placeholder"><span class="record-label">BOOGIE<br>WOOGIE</span><small>YOUR NEXT FAVORITE SONG</small></div>';delete $('current-cover').dataset.src;}const target=Math.max(0,playback.position+(playback.playing?Math.max(0,Date.now()/1000-playback.server_time):0));if(desired!==monitorSource){monitorSource=desired;video.pause();if(desired){video.src=desired;video.load();}else{video.removeAttribute('src');video.load();}}if(!playback.playing||!monitorWanted){video.pause();$('monitor-enable').hidden=!playback.playing;return;}if(video.readyState>=1){if(Math.abs(video.currentTime-target)>1.25)video.currentTime=Math.min(target,video.duration||target);video.play().then(()=>{$('monitor-enable').hidden=true;}).catch(()=>{$('monitor-enable').hidden=false;});}}
$('monitor').addEventListener('loadedmetadata',()=>{if(lastPlayback)syncMonitor(lastPlayback);});
$('monitor').addEventListener('error',()=>{if(monitorSource)toast('This playback file could not be loaded. Try another song.',true);});
$('monitor').volume=0.8;
$('volume').addEventListener('input',()=>{$('monitor').volume=Number($('volume').value);});
$('monitor-enable').addEventListener('click',()=>{monitorWanted=true;if(lastPlayback)syncMonitor(lastPlayback);});
async function control(action){try{monitorWanted=true;const playback=await api('/api/playback',{action});state.playback=playback;syncMonitor(playback);await refresh();}catch(error){toast(error.message,true);}}
$('play-button').addEventListener('click',()=>control(state.playback.playing?'pause':'start'));
$('skip-button').addEventListener('click',()=>control('skip'));
$('restart-button').addEventListener('click',()=>control('restart'));
setInterval(()=>{if(!lastPlayback?.song)return;const duration=lastPlayback.song.duration;const position=Math.min(duration,lastPlayback.position+(lastPlayback.playing?(Date.now()-lastPlayback.received)/1000:0));$('elapsed').textContent=timeLabel(position);$('total-time').textContent=timeLabel(duration);$('progress-fill').style.width=`${duration?Math.min(100,position/duration*100):0}%`;},200);
function openKeyEditor(){
 $('key-form').hidden=false;$('edit-key').setAttribute('aria-expanded','true');
 $('api-key-label').textContent=state.settings.key_configured?'Replacement API key':'OpenAI API key';
 $('api-key').value='';$('save-key').checked=true;$('api-key').focus();
}
function closeKeyEditor(){ $('api-key').value='';$('key-form').hidden=true;$('edit-key').setAttribute('aria-expanded','false'); }
function renderSettings(){
 const settings=state.settings, saved=settings.key_persisted, configured=settings.key_configured;
 $('key-status').textContent=saved?'API key saved':configured?'API key set':'Add cover art key';
 $('credential-card').classList.toggle('has-key',!!configured);
 $('credential-title').textContent=saved?'API key saved on this PC':configured?(settings.key_source==='environment'?'API key supplied by your system':'API key set for this session'):'No API key saved';
 $('credential-state').textContent=saved?'Saved for future sessions. The key is hidden.':configured?(settings.key_saved?'A different key is saved on this PC and will return after restart.':settings.key_source==='environment'?'Your system supplies this key when the studio starts. You can replace it with a saved key.':'This key will be cleared when the studio stops.'):'Add a key to generate OpenAI cover art. Local music and lyrics work without it.';
 $('key-storage-hint').textContent=settings.key_saved?'Uncheck for this session only; the previously saved key will return after restart.':'Uncheck to use this key for the current session only.';
 $('edit-key').textContent=configured?'Replace API key':'Add API key';$('forget-key').hidden=!configured&&!settings.key_saved;
 if(!settingsLoaded){$('image-model').value=settings.image_model||'gpt-image-2.5-sunburst';$('image-quality').value=settings.image_quality||'high';$('cover-limit').value=settings.cover_limit??20;$('cover-budget').value=settings.cover_budget??5;settingsLoaded=true;}
 const usage=settings.usage||{};$('cover-usage').textContent=`Today (UTC): ${usage.requests||0} cover requests · $${Number(usage.estimated_usd||0).toFixed(3)} estimated${usage.uncertain_requests?` · ${usage.uncertain_requests} request(s) awaiting confirmed usage`:''}`;
}
$('edit-key').addEventListener('click',openKeyEditor);
$('cancel-key').addEventListener('click',()=>{closeKeyEditor();$('edit-key').focus();});
$('key-form').addEventListener('submit',async event=>{
 event.preventDefault();const button=$('save-key-button');button.disabled=true;$('cancel-key').disabled=true;
 try{state.settings=await api('/api/settings',{api_key:$('api-key').value.trim(),save_key:$('save-key').checked});closeKeyEditor();renderSettings();$('edit-key').focus();toast(state.settings.key_persisted?'API key saved on this PC.':'API key set for this session.');}
 catch(error){toast(error.message,true);}finally{button.disabled=false;$('cancel-key').disabled=false;}
});
$('settings-form').addEventListener('submit',async event=>{
 event.preventDefault();const submit=event.submitter;submit.disabled=true;
 try{state.settings=await api('/api/settings',{image_model:$('image-model').value,image_quality:$('image-quality').value,cover_limit:Number($('cover-limit').value),cover_budget:Number($('cover-budget').value)});renderSettings();toast('Cover art settings saved.');}
 catch(error){toast(error.message,true);}finally{submit.disabled=false;}
});
let deletingKey=false;
$('forget-key').addEventListener('click',()=>{$('delete-key-error').hidden=true;$('delete-key-dialog').showModal();});
$('cancel-delete-key').addEventListener('click',()=>{if(!deletingKey)$('delete-key-dialog').close();});
$('delete-key-dialog').addEventListener('cancel',event=>{if(deletingKey)event.preventDefault();});
$('confirm-delete-key').addEventListener('click',async()=>{
 if(deletingKey)return;deletingKey=true;$('confirm-delete-key').disabled=true;$('cancel-delete-key').disabled=true;
 try{state.settings=await api('/api/settings/forget-key',{});closeKeyEditor();$('use-cover').checked=false;renderSettings();$('delete-key-dialog').close();$('edit-key').focus();toast('API key deleted from this studio.');}
 catch(error){$('delete-key-error').textContent=error.message;$('delete-key-error').hidden=false;}
 finally{deletingKey=false;$('confirm-delete-key').disabled=false;$('cancel-delete-key').disabled=false;}
});
$('player-url').value=`${location.origin}/player.html`;
$('rtmp-server').value='rtmps://a.rtmps.youtube.com/live2';
$('destination').addEventListener('change',()=>{$('rtmp-server').value=$('destination').value==='youtube'?'rtmps://a.rtmps.youtube.com/live2':'';});
$('broadcast-form').addEventListener('submit',async event=>{event.preventDefault();const button=$('go-live');button.disabled=true;try{state.broadcast=await api('/api/broadcast/start',{server:$('rtmp-server').value.trim(),stream_key:$('stream-key').value.trim(),orientation:$('orientation').value,confirmed:$('confirm-live').checked});$('stream-key').value='';$('confirm-live').checked=false;toast('Broadcast process started. Verify reception in your platform dashboard.');renderBroadcast();}catch(error){toast(error.message,true);}finally{button.disabled=false;}});
$('stop-broadcast').addEventListener('click',async()=>{try{state.broadcast=await api('/api/broadcast/stop',{});toast('Broadcast stopped.');renderBroadcast();}catch(error){toast(error.message,true);}});
function renderBroadcast(){const broadcast=state.broadcast||{};$('broadcast-badge').textContent=broadcast.reconnecting?'RECONNECTING':broadcast.running?'SENDING STREAM':'OFF AIR';$('go-live').hidden=!!broadcast.running;$('stop-broadcast').hidden=!broadcast.running;$('service-status').textContent=broadcast.running?'BROADCAST RUNNING':'LOCAL STATION';const message=$('broadcast-message');if(broadcast.running){message.hidden=false;message.textContent=broadcast.reconnecting?`Connection lost. Retrying the same playlist and destination (attempt ${broadcast.retry_count||1}). You can stop the broadcast below.`:`Sending ${broadcast.playlist_count} queued song(s) to ${broadcast.destination_host}. Confirm the live picture and sound in your platform dashboard.`;}else if(broadcast.exit_code!==null&&broadcast.exit_code!==undefined&&broadcast.exit_code!==0){message.hidden=false;message.textContent='The broadcast process stopped. Check your destination, stream key, and internet connection.';}else message.hidden=true;}
async function refresh(){if(refreshing)return;refreshing=true;try{state=await api('/api/state');renderLibrary();renderQueue();renderJobs();renderSettings();renderBroadcast();syncMonitor(state.playback);}catch(error){$('sidebar-engine').textContent='Station reconnecting…';}finally{refreshing=false;}}
async function refreshHealth(){try{const health=await api('/api/health');$('sidebar-engine').textContent=health.comfy?'YuE2 engine ready':'Music engine offline';$('comfy-detail').textContent=health.comfy?'Ready · 127.0.0.1:8188':'Start the local music engine';$('comfy-badge').textContent=health.comfy?'READY':'OFFLINE';$('comfy-badge').classList.toggle('error',!health.comfy);$('ollama-detail').textContent=health.ollama?`${health.ollama_model} · CPU`:'Local lyric writer unavailable';$('ollama-badge').textContent=health.ollama?'READY':'OFFLINE';$('ollama-badge').classList.toggle('error',!health.ollama);}catch{}}
refresh();refreshHealth();setInterval(refresh,1500);setInterval(refreshHealth,15000);
// Optional agent access uses the same visible station actions. It never exposes secrets or starts a public broadcast.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});register({name:'get_station_state',title:'Read station state',description:'Read the song library, production jobs, local playback and queue. Does not expose API or stream keys.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>api('/api/state')});register({name:'add_song_to_queue',title:'Queue a finished song',description:'Add a finished library song to the local station queue. Does not start public broadcasting.',inputSchema:{type:'object',properties:{song_id:{type:'string',pattern:'^[a-f0-9]{32}$'}},required:['song_id'],additionalProperties:false},execute:async input=>{if(!input||!/^[a-f0-9]{32}$/.test(input.song_id)||Object.keys(input).some(k=>k!=='song_id'))throw new Error('A valid song_id is required.');const result=await api('/api/queue',{song_id:input.song_id,action:'add'});await refresh();return result;}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
